// Real album artwork for category tiles and featured playlists (generated by
// scripts/build-covers.mjs into src/shared/covers.json).
import covers from '../../shared/covers.json'
import { FEATURED_PLAYLISTS } from '../../shared/catalog'
import type { Source } from '../../shared/protocol'

const presetCovers = covers.presets as Record<string, string[]>
const playlistCovers = covers.playlists as Record<string, string | null>

export function presetImages(id: string): string[] {
  return presetCovers[id] ?? []
}

export function playlistImage(provider: string, id: string): string | null {
  return playlistCovers[`${provider}:${id}`] ?? null
}

/** Images to show for whatever music source is selected. */
export function sourceImages(source: Source): string[] {
  switch (source.kind) {
    case 'preset':
      return presetImages(source.id)
    case 'artist':
      return source.image ? [source.image] : []
    case 'playlist': {
      const img = source.image ?? playlistImage(source.provider, source.id)
      return img ? [img] : []
    }
    case 'search':
    case 'blend':
      return []
  }
}

export const FEATURED_WITH_COVERS = FEATURED_PLAYLISTS.map((p) => ({ ...p, image: playlistImage(p.provider, p.id) }))
